export function demoScene(warmWeather){const c=warmWeather.condition,indoor=weatherExperience(warmWeather).indoor;return `<svg class="warm-scene" viewBox="0 0 420 310" role="img" aria-label="${indoor?'Weather through a window':c==='rain'?'Rain boots and an umbrella on a rainy path':'A gentle seasonal morning'} illustration"><defs><pattern id="warm-dots" width="9" height="9" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".6" fill="#85765a" opacity=".12"/></pattern></defs><ellipse cx="220" cy="158" rx="163" ry="131" fill="var(--warm-scene-bg)"/><path d="M27 262q170-48 362-4" fill="none" stroke="#c6c6a8" stroke-width="2"/><ellipse cx="221" cy="270" rx="108" ry="13" fill="#b9ccd0" opacity=".55"/><path d="M312 246q-9-50 15-89m-15 61q-24-17-27-37m34 9q23-3 32-20" stroke="#92a17a" stroke-width="3" fill="none"/><path d="M326 160q2-29 20-32q3 23-20 32m-37 24q-27-5-24-26q21 1 24 26m32 8q26-22 39-11q-11 18-39 11" fill="#b3ba8c"/>${indoor?'<g transform="translate(95 30) scale(2)">'+demoArt('window').replace(/<svg[^>]*>|<\/svg>/g,'')+'</g>':`<g transform="translate(96 12) scale(2.35)">${demoArt(c==='rain'?'umbrella':c==='snow'?'snow':c==='wind'?'leaf':c==='sun'?'sun':'cloud').replace(/<svg[^>]*>|<\/svg>/g,'')}</g><g transform="translate(84 154) scale(1.15)">${demoArt(c==='rain'?'boots':c==='snow'?'scarf':'layer').replace(/<svg[^>]*>|<\/svg>/g,'')}</g><g transform="translate(220 191) scale(.68)">${demoArt(c==='sun'?'water':'towel').replace(/<svg[^>]*>|<\/svg>/g,'')}</g>`}${c==='rain'&&!indoor?'<g stroke="#a7c1c6" stroke-width="3" stroke-linecap="round"><path d="m75 44-5 12m262 10-5 12M58 131l-5 12m292-26-5 12m-40-98-5 12"/></g>':''}<ellipse cx="220" cy="158" rx="163" ry="131" fill="url(#warm-dots)"/><path d="m62 228 4 8 8 1-6 6 2 8-8-4-7 4 1-8-6-6 8-1Z" fill="#dfbf81"/></svg>`;}
